window.APCH_SEARCH_INDEX = [{"u":"404.html","t":"Page Not Found","d":"The page you were looking for could not be found.","c":"Pages","s":[{"h":"404","a":"","t":""},{"h":"Page Not Found","a":"","t":"We couldn't find the page you're looking for. It might have been moved or deleted. Return to Homepage"}]},{"u":"about.html","t":"About Us","d":"Learn about The Apostles","c":"About Us","s":[{"h":"About The Apostles' Church","a":"","t":"Discover our purpose, mission, and vision as we seek to glorify God and serve our community through faith in Jesus Christ."},{"h":"Our Purpose","a":"purpose","t":"The purpose of The Apostles' Church is to glorify God by obeying the Great Commandment and the Great Commission, to minister to the needs of both members and non-members as we are able, and to carry out all things related to advancing the Kingdom of Jehovah God. \"Teacher, which is the greatest commandment in the Law?\" "},{"h":"Our Mission","a":"mission","t":"To produce disciples of Jesus Christ involved in five essential areas of Christian life and ministry:"},{"h":"Worship (Celebrating)","a":"","t":"\"To love God with all your heart, soul, mind, and strength\" (Deuteronomy 6:4-5; Matthew 22:36-40)"},{"h":"Ministry (Caring)","a":"","t":"\"Love your neighbor as yourself\" (Matthew 22:36-40)"},{"h":"Evangelism (Cultivating)","a":"","t":"\"Go and make disciples of all nations\" (Matthew 28:18-20)"},{"h":"Discipleship (Communicating)","a":"","t":"\"Teach them to observe all that I have commanded you\" (Matthew 28:18-20)"},{"h":"Community (Unity)","a":"","t":"\"That they all may be one... that the world may believe\" (John 17:21)"},{"h":"Our Objectives","a":"objectives","t":"To fulfill our mission and purpose, we are committed to the following objectives: 1 To proclaim the Gospel of the Kingdom of God by any available means consistent with the teaching of God's Word. 2 To establish Church congregations having their own leadership and spiritual authority. 3 To provide ministries and service"},{"h":"Join Us in Our Mission","a":"","t":"Become part of a community dedicated to worship, ministry, evangelism, discipleship, and unity in Christ. Become an Apostle Contact Us"}]},{"u":"aboutAffiliation.html","t":"Affiliation","d":"How The Apostles","c":"About Us","s":[{"h":"Our Affiliation & Governance","a":"","t":"Understanding our autonomous governance while maintaining strategic partnerships for kingdom advancement."},{"h":"Our Affiliation Statement","a":"affiliation","t":"The Apostles' Church maintains a balanced approach to ecclesiastical relationships—exercising our God-given autonomy while engaging in meaningful partnerships that advance the Gospel and strengthen the global body of Christ. This Apostles' Church is autonomous and maintains the right to govern its own affairs, independ"},{"h":"Current Strategic Partnership","a":"","t":""},{"h":"Pentecostal Fellowship of Zambia","a":"","t":"An association of Pentecostal churches in Zambia committed to unity, evangelism, and spiritual renewal Strategic Partner Since 2010"},{"h":"Our Principles of Autonomous Governance","a":"","t":"Our autonomy is exercised under the following biblical principles that guide our governance and decision-making:"},{"h":"Biblical Authority","a":"","t":"Final authority in all matters rests with Scripture alone, not external denominational structures."},{"h":"Local Governance","a":"","t":"Each congregation is led by locally-appointed elders under Christ's headship."},{"h":"Doctrinal Integrity","a":"","t":"We maintain freedom to teach and practice biblical truth without compromise."},{"h":"Strategic Partnership","a":"","t":"We voluntarily partner with like-minded ministries for greater Gospel impact. \"Christ is the head of the church, his body, of which he is the Savior.\" — Ephesians 5:23 Our governance structure reflects our conviction that Christ alone is the head of His Church. All authority, decisions, and partnerships are submitted t"},{"h":"Our Beliefs","a":"","t":"Explore our Articles of Faith and foundational beliefs that guide our doctrine and practice. Read Articles of Faith"},{"h":"Our Mission","a":"","t":"Learn about our purpose, mission, and objectives as we seek to advance God's kingdom. About The APCH"}]},{"u":"aboutGovernance.html","t":"Church Governance","d":"The biblical structure and leadership councils that guide The Apostles","c":"About Us","s":[{"h":"Church Governance","a":"","t":"Understanding the biblical structure and leadership framework that guides The Apostles' Church"},{"h":"Divine Order in Leadership","a":"","t":"Biblical governance for effective ministry and spiritual guidance \"For God is not a God of disorder but of peace—as in all the congregations of the Lord's people.\" — 1 Corinthians 14:33 The Apostles' Church is organized and governed by councils composed of dedicated committees responsible for coordinating and synchroni"},{"h":"Governance Structure","a":"","t":"Two complementary systems working in harmony"},{"h":"Ecumenical Committees","a":"","t":"Spiritual Guidance & Doctrine Responsible for directing all ecumenical activities including doctrinal teaching and guardianship of the Church. These committees ensure the purity of doctrine and spiritual integrity of all church activities. Doctrinal Committee Oversees biblical teaching and ensures doctrinal purity Wors"},{"h":"Administration Committees","a":"","t":"Management & Operations Oversees all administrative and management functions in the Church. These committees ensure efficient operations, financial stewardship, and proper resource management. Finance Committee Manages church finances and budgeting Facilities Committee Oversees church property and maintenance Personnel"},{"h":"Council Hierarchy","a":"","t":"Three levels of governance working in unity Branch Council Local Congregation Leadership Made up of all leaders of the congregation chaired by the Pastor and deputised by the Evangelist. Oversees the congregation and coordinates all Branch Subcommittees. Regional Council Multi-Congregation Oversight A two-tier system, "},{"h":"Biblical Foundation","a":"","t":"Scriptural principles guiding our governance \"Obey your leaders and submit to them, for they keep watch over your souls as those who will give an account.\" Hebrews 13:17 \"The elders who direct the affairs of the church well are worthy of double honor, especially those whose work is preaching and teaching.\" 1 Timothy 5:"},{"h":"Our Constitution","a":"constitution-title","t":"The founding document that sets out our beliefs, structure and the way the church is governed"},{"h":"Constitution of The Apostles' Church in Zambia","a":"","t":"Revised September 1991 · 89 pages · PDF, 420 KB It covers: Aims, objectives and basis of faith Church branches and membership District, Provincial and National councils The Synod and the General Conference Leadership positions and qualifications Financial matters and registered trustees Baptism, marriage, healing and o"},{"h":"Learn More About Our Church","a":"","t":"Explore how our governance structure supports effective ministry and spiritual growth across all levels of our church community. Read the Constitution Church Structure View Activities"}]},{"u":"aboutSecretariat.html","t":"About Us","d":"The mission, leadership and apostolic foundations of The Apostles","c":"About Us","s":[{"h":"About The Apostles' Church","a":"","t":"Discover our mission, leadership, and the divine purpose that guides our ministry"},{"h":"Our Divine Mandate","a":"","t":"A Church Built on Apostolic Foundations \"Go therefore and make disciples of all nations, baptizing them in the name of the Father and of the Son and of the Holy Spirit, teaching them to observe all that I have commanded you.\" — Matthew 28:19-20 The Apostles' Church (APCH) is a vibrant Christian community committed to f"},{"h":"The Secretariat","a":"","t":"Central Management Committee & Administrative Heart The APCH Secretariat serves as the Central Management Committee and administrative organ that oversees the day-to-day activities of the Church from the Head Office. As the operational hub of our ministry, the Secretariat ensures smooth coordination, efficient manageme"},{"h":"Secretariat Structure","a":"","t":"Key Components of Our Administrative Leadership General Secretary Chief administrative officer responsible for overall coordination of church operations, record-keeping, and implementation of Synod Executive decisions. General Treasurer Oversees all financial matters including budgeting, accounting, stewardship of reso"},{"h":"Our Core Values","a":"","t":"Principles That Guide Our Ministry Biblical Authority We submit to the absolute authority of Scripture as God's inspired Word and final authority in all matters of faith and practice. Prayerful Dependence We maintain constant communion with God through prayer, recognizing our complete dependence on His guidance and pow"},{"h":"Secretariat Leadership","a":"","t":"Dedicated Servants Guiding Our Ministry General Secretary Chief Administrative Officer Provides overall administrative leadership, implements Synod Executive decisions, and ensures efficient coordination of all church operations. General Treasurer Financial Steward Oversees financial management, ensures proper stewards"},{"h":"Join Our Community","a":"","t":"Discover how you can become part of our vibrant church family and participate in the transformative work God is doing through The Apostles' Church. View Our Activities Church Structure Governance"}]},{"u":"articles.html","t":"Articles of Faith","d":"Our foundational beliefs that guide our faith and practice as followers of Christ.","c":"Faith & Beliefs","s":[{"h":"Articles of Faith","a":"","t":"Our foundational beliefs that guide our faith and practice as followers of Christ. Print or save as PDF"},{"h":"Outline","a":"","t":""},{"h":"Faith","a":"","t":"The following are the articles of Faith of The Apostles' Church, our foundational beliefs that guide our faith and practice as followers of Jesus Christ. \"Now faith is confidence in what we hope for and assurance about what we do not see.\" — Hebrews 11:1"},{"h":"Scripture","a":"scripture","t":"We believe the Holy Bible, both Old and New Testaments, is the inspired Word of Jehovah God, without any error as originally given. It is the all-sufficient and supreme authority in matters of faith, doctrine, and spiritual living. \"All Scripture is God-breathed and is useful for teaching, rebuking, correcting and trai"},{"h":"God","a":"god","t":"We believe in Jehovah God as the Supreme Divine Creator and one eternal God. He exists in three persons: Father, Son, and Holy Spirit—co-equal and co-eternal. \"In the beginning God created the heavens and the earth.\" — Genesis 1:1"},{"h":"Jesus Christ","a":"jesus","t":"We believe in Jesus Christ as the eternal Son of God incarnate. The incarnation includes the divine conception, virgin birth, and true humanity of Jesus Christ, yet without sin. His death was a voluntary substitutionary atonement for our sins. His resurrection and ascension were bodily, as His return will be. Meanwhile"},{"h":"The Holy Spirit","a":"holy-spirit","t":"We believe in the Holy Spirit as the power of Jehovah God who convicts people of sin, regenerates them, baptizing them into the body of Jesus Christ at their conversion. The Holy Spirit seals, indwells, sanctifies, and fills believers, producing in them the fruits of the Spirit and power for service. \"But the Advocate,"},{"h":"Life","a":"life","t":"We believe in the sanctity of life in all its forms, as all life comes from God and bears His image. Every human life has intrinsic value and dignity from conception to natural death. \"So God created mankind in his own image, in the image of God he created them; male and female he created them.\" — Genesis 1:27"},{"h":"Human","a":"human","t":"We believe that humans were created both male and female in the image of God but were tempted and fell into sin. Therefore, all humans are born with a sinful nature and, unless saved by the grace of Jehovah God through Jesus Christ, stand eternally condemned. \"For all have sinned and fall short of the glory of God.\" — "},{"h":"Death","a":"death","t":"We believe that physical death is a consequence of sin but that through Christ's resurrection, death has been conquered. For believers, death is the gateway to eternal life with God. \"Where, O death, is your victory? Where, O death, is your sting?\" — 1 Corinthians 15:55"},{"h":"Salvation","a":"salvation","t":"We believe that salvation is a free gift of God's grace, received through faith in Jesus Christ alone. It is not earned by good works but results in good works as evidence of genuine faith. \"For it is by grace you have been saved, through faith—and this is not from yourselves, it is the gift of God.\" — Ephesians 2:8"},{"h":"Church","a":"church","t":"We believe the Church is the Ekklesia of God, the body and Kingdom of Jesus Christ of which Jesus Christ is the Head and King built on the foundation rock of the Apostles. We also believe in a regenerated Church membership: that is, the Ekklesia is composed of believers from every tribe, tongue, race and nation, who, o"},{"h":"Baptism","a":"baptism","t":"We believe that baptism is by immersion in the name of the Father and of the Son and of the Holy Spirit (i.e. Triune immersion) and that the Lord's Supper is a memorial to the suffering and death of Jesus Christ on the cross. These are ordinances to be observed by the Church in its present age. \"Go and make disciples o"},{"h":"Resurrection","a":"resurrection","t":"We believe in the bodily resurrection of the living dead, the everlasting blessedness of the saved in heaven, and the everlasting punishment and separation from Jehovah God of the unsaved in hell. \"How are the dead raised? What is sown perishable is raised imperishable, a spiritual body in glory. Though afflicted and s"},{"h":"Culture","a":"culture","t":"We believe that culture everywhere in the world is a sum total of the lived experiences under particular material conditions created by a given social, economic and political order and this plays an indispensable role in the spirituality of believers. Aspects of culture that are consistent with the Word of Jehovah God "},{"h":"Eschatology","a":"eschatology","t":"We believe that there will be signs and events marking the end times, including the rapture of the Church when Christ returns and true believers are caught up to meet Him in the air, the revelation of the man of sin, and the great tribulation period. We also affirm the judgment of the nations, where all people will app"}]},{"u":"communityActivities.html","t":"Church Activities","d":"Worship, fellowship and outreach activities at The Apostles","c":"Community","s":[{"h":"Church Activities","a":"","t":"Join us in faith-building activities that strengthen our community and deepen our relationship with God"},{"h":"Building Our Faith Community","a":"","t":"Engage in activities that nurture spiritual growth and fellowship \"And let us consider how we may spur one another on toward love and good deeds, not giving up meeting together, as some are in the habit of doing, but encouraging one another—and all the more as you see the Day approaching.\" — Hebrews 10:24-25 The Apostl"},{"h":"Holy Convocation","a":"","t":"Divine Gathering & Worship A holy fellowship of Yahweh with the saints. It involves prayers, the sharing of psalms, and study of the Word of Yahweh. The saints come into Yahweh's presence in this manner thrice a week on the fourth, fifth and eighth day. This is the day when Yahweh gave light to the dark heavens and ear"},{"h":"Solemn Feasts","a":"","t":"Annual Spiritual Conferences Seven days Holy Feasts held thrice a year in April, July and October with neither the leaven of malice and wickedness; but with the unleavened bread of sincerity and truth which is Yehoshua HaMeshiach. For Christ, our Passover lamb, has been sacrificed. Therefore let us keep the Festival, n"},{"h":"Hossanah","a":"","t":"Daily Worship & Thanksgiving Conducted every morning, afternoon and evening of each day of the week to dedicate and give thanks for the day and night to Yahweh. The morning and evening sessions are done by each group of neighbouring households while the afternoon session is conducted by individuals wherever they may be"},{"h":"Prayer Retreats","a":"","t":"Sacred Times of Deep Communion Traditionally, prayer retreats are held every Friday and Tuesday. Special retreats are organised on request and directive from Yahweh. These prayers take place at retreat centres called Rushanga, the Sacred Place and/or Holy Mountain. But when you pray, go into your room, close the door a"},{"h":"Bible Study","a":"","t":"Systematic Scriptural Exploration Indepth systematic exploration of sacred scriptures to build and equip believers with effective and efficient understanding and application of the Word of Yahweh. All Scripture is God-breathed and is useful for teaching, rebuking, correcting and training in righteousness. 2 Timothy 3:1"},{"h":"Community Outreach","a":"","t":"Evangelism & Church Planting Home visitation conducted by congregation leadership and reaching out to the world with the gospel of the Kingdom of Yahweh and planting churches by the team of evangelists and preachers. Therefore go and make disciples of all nations, baptizing them in the name of the Father and of the Son"},{"h":"Family Ministry","a":"","t":"CHINAI Fellowships The Apostles Church conducts weekly gatherings, seminars and other activities on Thursday, Friday or Saturday that inculcate and uphold values and principles from the Biblical Worldview on marriage, parenting and family life through CHINAI (which means the fifth element) Fellowships for the Women, Me"},{"h":"Weekly Schedule","a":"schedule","t":"Regular activities that build our spiritual foundation"},{"h":"Sunday Service","a":"schedule","t":"Every Sunday 10:00 - 12:30 Main Divine Service with worship, teaching, and communion"},{"h":"Midweek Bible Study","a":"","t":"Wednesday Evenings 18:00 - 19:00 Deep dive into Scripture with group discussion and prayer"},{"h":"Prayer Meetings","a":"","t":"Tuesday & Friday 18:00 - 21:00 Corporate prayer for church, community, and global needs"},{"h":"Join Our Activities","a":"","t":"Whether you're looking to deepen your faith, serve the community, or connect with other believers, there's a place for you in our church activities. View Schedule Church Structure Church Delimitation"}]},{"u":"communityDelimitation.html","t":"Church Structure","d":"The organisational structure of The Apostles","c":"Community","s":[{"h":"Church Organizational Structure","a":"","t":"Understanding the biblical and efficient structure that enables effective ministry across all levels of The Apostles' Church. The Apostles' Church is organized into four distinct administrative levels, each designed for effective ministry, leadership, and spiritual growth."},{"h":"Preaching Point","a":"","t":"Satellite Assembly Point The smallest assembly unit of The Apostles' Church, operating as a satellite point for the nearest branch. These are strategic locations for outreach and community engagement. Leadership: Appointed Teacher assisted by Deacon, Secretary, and Treasurer Purpose: Local outreach and foundational dis"},{"h":"Branch","a":"","t":"Foundation of APCH The foundational unit of The Apostles' Church, consisting of a congregation with established leadership and regular worship services. Each branch serves as a spiritual home for members in a specific locality. Membership: 40-144 baptized members Leadership: Pastor with appointed elders Growth Strategy"},{"h":"Region","a":"","t":"Geographical Administration A defined geographical area containing multiple branches, configured and recommended by the Secretariat and approved by the Synod Executive. Regions provide oversight and coordination for ministry across larger areas. Requirements: Minimum 1,000 baptized members Governance: Regional leadersh"},{"h":"The General Conference","a":"","t":"Supreme Governing Body The highest governing authority of The Apostles' Church, representing the entire membership. The General Conference makes key decisions, provides spiritual direction, and serves the Lord's Table during its meetings. Meetings: Quarterly (April, July, October) Authority: Supreme decision-making bod"},{"h":"General Conference Schedule","a":"","t":"Following the biblical pattern established in Deuteronomy 16, The Apostles' Church holds three General Conferences each year to celebrate, make decisions, and serve the Lord's Table. April First Quarter Conference Spring gathering focusing on spiritual renewal, strategic planning for the year, and celebrating new begin"},{"h":"Leadership Structure","a":"","t":"General Conference Supreme Governing Body Synod Executive Executive Leadership Council Secretariat Administrative Office Regional Council Geographical Oversight Branch Pastors Local Congregation Leaders Elders Council Spiritual Guidance Teachers Preaching Point Leaders Deacons Service & Support"},{"h":"Connect with Our Church Structure","a":"","t":"Find your place in our organized, biblical church structure and grow in ministry alongside fellow believers. Join a Local Branch Find a Preaching Point"}]},{"u":"communityHistory.html","t":"Our History","d":"The story of how God established The Apostles","c":"Community","s":[{"h":"Our Historical Journey","a":"","t":"From divine calling to regional impact: The story of how God established The Apostles' Church across Southern and Central Africa. 1914"},{"h":"The Divine Calling","a":"","t":"Isaac Kachada Chiumbu experienced glossolalia while working underground at Etna mine in Zimbabwe in 1914. Like Moses before the burning bush or Saul on the road to Damascus, he was called without human mediation to expand the Mission of the Kingdom of Heaven in Africa. This marked the birth of an authentic endogenous c"},{"h":"Northward Expansion Commission","a":"","t":"Reverend Samson Sibanda Kantini and his wife, Prophetess Sophia Mandhiyamba, received their divine commission under the leadership of Prophet Isaac Kachada Chiumbu. Their mission: to lead the expansion of the Apostolic work north of the Zambezi River into present-day Zambia, Malawi, Mozambique, and the Democratic Repub"},{"h":"Foundation and Growth","a":"","t":"The Mission took root and developed organically, following Biblical methods modeled in the Book of Acts while maintaining its foundation in Genesis. In Zimbabwe: The work flourished through the pioneering efforts of Prophet Isaac Kachada Chiumbu and his brother, Reverend Levy Savvya Nyirenda Nyangamire. In Zambia: The "},{"h":"Regional Impact","a":"","t":"The Apostolic message spread beyond Zimbabwe and Zambia to the wider Southern, Central, and Eastern African regions. The movement maintained its distinctive character as an authentic African church, rooted in Biblical patterns rather than Western ecclesiastical structures. Congregations multiplied as the Gospel was pro"},{"h":"Distinctive Message","a":"","t":"The Gospel proclaimed by Prophet Isaac Chiumbu was received as outright rebellion against: Western Christian perspectives and imperialism African occultic practices and traditional spiritualism Religious formalism without spiritual power The Mission established a unique identity as a church born of the Holy Spirit, not"},{"h":"Our Missionary Pioneers","a":"","t":""},{"h":"Prophet Isaac Kachada Chiumbu","a":"","t":"Prophet & 1st General Overseer"},{"h":"Rev. Samson Sibanda Kantini","a":"","t":"Missionary Pioneer"},{"h":"Prophetess Sophia Mandhiyamba Kantini","a":"","t":"Missionary & Prophetess"},{"h":"Rev. Levy Savvya Nyirenda Nyangamire","a":"","t":"Missionary in Zimbabwe"},{"h":"Prophetess Maria Magumuza Nyangamire","a":"","t":"Missionary & Prophetess"},{"h":"Rev. Joe Chimangeni","a":"","t":"Prophet & 2nd General Overseer"},{"h":"Prophetess Elinah Kantini Chimangeni","a":"","t":"Missionary & Prophetess"},{"h":"Rev. Moffat Mukombe","a":"","t":"Prophet & 3rd General Overseer"},{"h":"Rev. Josaiah Sibanda Kantini","a":"","t":"Missionary & 4th General Overseer"},{"h":"Prophetess Dorothy Nyangamire Kantini","a":"","t":"Missionary & Prophetess"},{"h":"Rev. Elias Paradza","a":"","t":"Missionary"},{"h":"Prophetess Mariah Kantini Paradza","a":"","t":"Missionary & Prophetess"},{"h":"Rev. Rodger Paradza","a":"","t":"Missionary"},{"h":"Prophetess Joanah Kantini Paradza","a":"","t":"Missionary & Prophetess"},{"h":"Rev. White Johanne Siang'andu","a":"","t":"Missionary & 5th General Overseer"},{"h":"Rev. Amos Munachinyuka","a":"","t":"Missionary"},{"h":"Rev. Stephen Moses Kantini","a":"","t":"Missionary & Architect"},{"h":"Prophetess Susanna Makoni Kantini","a":"","t":"Prophetess & Missionary"},{"h":"Rev. Zephania Mataga","a":"","t":"Missionary"},{"h":"Prophetess Eniah Mataga","a":"","t":"Missionary & Prophetess"},{"h":"Rev. William Luwanika","a":"","t":"Missionary"},{"h":"Rev. Luke Chidzanira","a":"","t":"Missionary"},{"h":"Rev. Elizabeth Kantini Chidzanira","a":"","t":"Missionary"},{"h":"Our Enduring Legacy","a":"","t":"For over a century, The Apostles' Church has maintained its commitment to authentic Biblical Christianity, contextual ministry, and Spirit-empowered transformation. 108+ Years of Ministry 4+ African Nations Biblical Foundational Pattern Spirit-Led Growth & Ministry"},{"h":"Become Part of Our Continuing Story","a":"","t":"Join a church with a rich heritage of authentic faith, Spirit-empowered ministry, and commitment to Biblical truth. Join Our Heritage Learn About Our Mission"}]},{"u":"digitLibrary.html","t":"Digital Library","d":"Explore our digital library of Christian resources, sermons, Bible studies, and educational materials for spiritual growth.","c":"Digital Library","s":[{"h":"Digital Library","a":"library-title","t":"Explore our comprehensive collection of Christian resources, sermons, Bible studies, and educational materials for spiritual growth and discipleship. All Resources Sermons Bible Studies Articles Books Videos Audio New Additions Most Popular"},{"h":"Featured Resources","a":"featured-resources","t":"Sermon Series"},{"h":"The Gospel of John: A Deep Dive","a":"","t":"Pastor John Smith 45 min A comprehensive 12-part sermon series exploring the profound truths in the Gospel of John, focusing on the deity of Christ and His mission. Listen Now Download Bible Study"},{"h":"Understanding the Book of Romans","a":"","t":"Dr. Michael Chen Study Guide An in-depth 8-week Bible study guide exploring Paul's letter to the Romans, with discussion questions and practical applications. Study Online PDF Article"},{"h":"The Power of Persistent Prayer","a":"","t":"Sarah Johnson 15 min read Explore biblical principles of persistent prayer and how to develop a consistent prayer life that transforms your relationship with God. Read Article Save Video Series"},{"h":"Christian Foundations for New Believers","a":"","t":"Elder James Wilson 10 episodes A video series designed to help new Christians understand the basics of faith, baptism, prayer, and living a Christian life. Watch Series Share E-Book"},{"h":"Walking in the Spirit: A Practical Guide","a":"","t":"Rev. David Miller 240 pages Learn how to cultivate sensitivity to the Holy Spirit's guidance in everyday life through biblical principles and practical exercises. Read E-Book EPUB Audio Podcast"},{"h":"Daily Devotional Reflections","a":"","t":"Various Elders Daily episodes Daily 10-minute audio devotionals covering various books of the Bible with practical applications for modern Christian living. Listen Now Subscribe"},{"h":"Featured Collections","a":"collections-title","t":""},{"h":"Bible Study Series","a":"","t":"42 resources Gospel Studies (12) Paul's Letters (8) Old Testament (15) Prophecy (7) Explore Collection"},{"h":"Family & Marriage","a":"","t":"28 resources Marriage Counseling (6) Parenting (8) Family Devotions (7) Relationships (7) Explore Collection"},{"h":"Church History","a":"","t":"35 resources Early Church (9) Reformation (8) Modern Church (10) Biographies (8) Explore Collection"},{"h":"Latest Additions","a":"latest-title","t":"Document"},{"h":"Church Constitution (1991)","a":"","t":"Our beliefs, church structure, leadership and governance, as revised in September 1991. PDF, 89 pages. Read Now New"},{"h":"Youth Ministry Toolkit","a":"","t":"Resources for engaging youth in meaningful spiritual conversations. Explore New"},{"h":"Financial Stewardship","a":"","t":"Biblical principles for managing finances as faithful stewards. Learn More New"},{"h":"Prayer Journal Template","a":"","t":"Printable prayer journal to track your prayer journey. Download"},{"h":"Stay Updated","a":"newsletter-title","t":"Subscribe to our newsletter to receive weekly updates on new resources, featured content, and spiritual insights. Subscribe We respect your privacy. Unsubscribe at any time."}]},{"u":"giving.html","t":"Giving & Stewardship","d":"Support the mission of The Apostles","c":"Giving","s":[{"h":"Giving & Stewardship","a":"","t":"Partner with us in ministry through your faithful giving and support our mission to spread God's Word throughout our community and beyond. \"Each of you should give what you have decided in your heart to give, not reluctantly or under compulsion, for God loves a cheerful giver.\" — 2 Corinthians 9:7"},{"h":"Biblical Principles of Giving","a":"why-give-title","t":""},{"h":"An Act of Worship","a":"","t":"Giving is an expression of gratitude and worship to God, acknowledging that everything we have comes from Him. It's a tangible way to honor God with our resources."},{"h":"Supporting Ministry","a":"","t":"Your giving enables us to maintain our facilities, support missionaries, fund outreach programs, and provide resources for spiritual growth in our community."},{"h":"Building Community","a":"","t":"Through collective giving, we can support those in need, provide food and shelter, and create opportunities for fellowship and spiritual development."},{"h":"Ways to Give","a":"giving-methods-title","t":"Online Giving Mobile Money Bank Transfer In Person"},{"h":"Secure Online Giving","a":"online-content","t":"Card giving online is coming soon. Until then, please give by Mobile Money, bank transfer or in person. Your Information Giving Amount K50 K100 K200 K500 K1,000 K Giving Frequency One-Time Weekly Monthly Fund Allocation General Fund Church Operations Missions Local & Global Outreach Benevolence Helping Those in Need Bu"},{"h":"Mobile Money","a":"text-content","t":"Give from your phone using Airtel Money or MTN MoMo Mobile Money Details: Airtel Money: [To be confirmed] MTN MoMo: [To be confirmed] Registered Name: [To be confirmed] Note: Check that the registered name matches before you send. Please send your name and the purpose of your gift (e.g. tithe, offering, building fund) "},{"h":"Bank Transfer","a":"bank-content","t":"Make a one-time or standing-order transfer from your bank account Church Banking Information: Bank: [To be confirmed] Branch: [To be confirmed] Account Name: [To be confirmed] Account Number: [To be confirmed] Branch / Sort Code: [To be confirmed] SWIFT Code (international): [To be confirmed] Important Notes: Include y"},{"h":"In Person","a":"check-content","t":"Give during services or at the church office During Services Give your offering or tithe during our Sunday worship services. At the Church Office The Apostles' Church CH80/01 Off Zambezi Road Lusaka, Zambia Monday-Friday, 10:00 AM - 4:00 PM Receipts: Ask for a receipt when you give at the church office, and include you"},{"h":"Your Giving Makes a Difference","a":"impact-title","t":"42% Supports Local Missions Feeding programs, shelters, and community outreach 28% Church Operations Facilities, staff, and ministry resources 20% Global Missions Supporting missionaries and international projects 10% Benevolence Fund Emergency assistance for families in need"},{"h":"Recent Impact Stories","a":"","t":"Community Kitchen Your giving helped serve over 5,000 meals to families in need last month. Youth Ministry Funded summer camp scholarships for 45 students who couldn't otherwise attend. International Mission Supported clean water projects serving 3 villages in developing nations."},{"h":"Frequently Asked Questions","a":"faq-title","t":"Can I give online with a card? Online card giving is coming soon. For now, please give by Mobile Money, bank transfer or in person. This website does not collect or store any payment details. Will I receive a receipt for my giving? Yes. Receipts are issued at the church office. For Mobile Money or bank transfers, send "}]},{"u":"index.html","t":"Home","d":"Join The Apostles","c":"Home","s":[{"h":"THE APOSTLES' CHURCH","a":"","t":"Discover the truth and wisdom found in God's Word, and experience the peace and purpose He has planned for you. Take the first step towards a life of faith, healing, and hope by starting your journey today. START YOUR JOURNEY HERE"},{"h":"Wisdom from Our Elders","a":"elders-title","t":"Our church elders have been the foundation of wisdom, faith, and guidance for generations. Their experiences, prayers, and teachings have shaped our spiritual journey and strengthened our community. \"Faith is not just believing—it's trusting God's plan even when you cannot see the path ahead.\" — Elder John \"In prayer, "},{"h":"Begin Your Journey with Christ","a":"journey-title","t":"In Seven Transformative Steps \"Come, follow me,\" Jesus said, \"and I will make you fishers of men.\" — Matthew 4:19 Begin your transformational journey with Christ in seven meaningful steps."},{"h":"Your Journey Map","a":"","t":"Step 1: Believe Step 2: Repent Step 3: Walk in His Word Step 4: Join Step 5: Share the Good News Step 6: Serve with Love Step 7: Stay Faithful 1"},{"h":"Believe in Him","a":"step1-title","t":"\"For God so loved the world that He gave His one and only Son, that whoever believes in Him shall not perish but have eternal life.\" — John 3:16 Faith in Jesus is the foundation of your journey. It starts with believing that He is the Son of God who came to save us from sin. His love is unconditional, and His grace is "},{"h":"Repent and Be Baptized","a":"step2-title","t":"\"Repent, then, and turn to God, so that your sins may be wiped out, that times of refreshing may come from the Lord.\" — Acts 3:19 Repentance is turning away from sin and choosing to follow Christ. It is not just about feeling sorry for mistakes but making a heart-driven decision to live according to God's will. Baptism"},{"h":"Walk in His Word","a":"step3-title","t":"\"Your word is a lamp to my feet and a light to my path.\" — Psalm 119:105 God's Word is our guide through life. The Bible teaches, corrects, and encourages us, helping us grow spiritually. Daily prayer and study of the Scriptures strengthen your faith and deepen your relationship with God. When you seek His guidance and"},{"h":"Join Our Church Family","a":"step4-title","t":"\"They devoted themselves to the apostles' teaching and to fellowship, to the breaking of bread and to prayer.\" — Acts 2:42 Faith is strengthened in community. God designed the church to be a family of believers who support, uplift, and encourage one another. Through worship, fellowship, and service, you will find a pla"},{"h":"Share the Gospel","a":"step5-title","t":"\"Go into all the world and preach the gospel to all creation.\" — Mark 16:15 Faith is not meant to be kept to yourself. As believers, we are called to spread the good news of Jesus Christ. Share your testimony with friends, family, and those around you. Let your actions reflect God's love and grace, showing others the t"},{"h":"Serve Others with Love","a":"step6-title","t":"\"Each of you should use whatever gift you have received to serve others, as faithful stewards of God's grace in its various forms.\" — 1 Peter 4:10 True discipleship is demonstrated through service. Whether through acts of kindness, volunteering, or ministry, serving others is a powerful way to reflect Christ's love. Fi"},{"h":"Remain Faithful and Endure","a":"step7-title","t":"\"But the one who stands firm to the end will be saved.\" — Matthew 24:13 The Christian journey is not always easy, but perseverance in faith brings eternal rewards. Stay strong in your walk with Christ through prayer, worship, and continued spiritual growth. Surround yourself with a faith-filled community that encourage"},{"h":"Are you ready to take the next step?","a":"","t":"Join us this Sunday or reach out to learn how to begin your journey with Christ. JOIN US TODAY"},{"h":"Explore Our Resources","a":"resources-title","t":"Discover articles, studies, and materials to strengthen your faith and understanding of God's Word."},{"h":"What Is the Coming of Christ?","a":"coming-christ-card","t":"Understanding biblical prophecy about Christ's return and what it means for believers today. The Coming of Christ refers to the promised return of Jesus Christ to consummate God's redemptive plan for humanity and creation. The Holy Bible teaches that Jesus, who ascended bodily into heaven, will return personally, visib"},{"h":"Finding Healing and Hope","a":"healing-hope-card","t":"A compassionate guide to overcoming self-harm through faith, community, and God's healing love. Healing and Hope in the Gospel Healing and hope are central to the Gospel of Jesus Christ. The Apostles' Church believes that Jehovah God is both willing and able to bring healing—spiritual, emotional, and physical—according"},{"h":"Biblical Perspective on Equality","a":"equality-card","t":"What the Bible teaches about human dignity, justice, and our call to love all people equally. The Apostles' Church affirms that all human beings are equal in worth and dignity before Jehovah God, having been created in His image (Genesis 1:26–27). Biblical equality is rooted in creation, redemption, and God's righteous"},{"h":"Select a Topic That Interests You","a":"topics-title","t":"Bible Questions Answered Clear answers to common questions about scripture and Christian living. Explore Peace & Happiness Biblical principles for finding true peace and lasting joy in Christ. Explore Faith in God Strengthening your trust and developing a deeper relationship with God. Explore Marriage & Family Biblical"},{"h":"Get Involved in Our Community","a":"involve-title","t":""},{"h":"Try Our Bible Course","a":"get-involved","t":"Join our free interactive Bible study program tailored for all knowledge levels. Enroll Now"},{"h":"Attend a Meeting","a":"","t":"Join us for worship, fellowship, and spiritual growth at our weekly services. View Schedule"},{"h":"Request a Visit","a":"","t":"Have one of our members visit you for prayer, conversation, or Bible study. Schedule Visit"},{"h":"The Apostles' Church—Who Are We?","a":"","t":"We come from hundreds of ethnic and language backgrounds, yet we are united by common goals. Above all, we want to honor God, follow the teachings of Jesus Christ, and share His love with the world. Our community is built on the foundation of apostolic teaching, sincere faith, and genuine fellowship. We believe in the "}]},{"u":"membership.html","t":"Membership","d":"How to become a member of The Apostles","c":"Community","s":[{"h":"Church Membership","a":"","t":"Joining our community of faith, growing together in Christ, and serving God's purpose."},{"h":"Description","a":"membership","t":"Membership in The Apostles' Church consists of all persons who have met the requirements for membership, having been approved by the congregation and are listed on the membership role. We maintain separate registers for different stages of spiritual journey:"},{"h":"Children's Register","a":"","t":"Children consecrated in the church are listed here until age 18. Each child receives a Certificate of Consecration."},{"h":"Baptism Register","a":"","t":"All baptized members receive a Certificate of Baptism and are formally recorded in our membership database."},{"h":"Active Membership","a":"","t":"Fully committed members who participate in church life, voting, and leadership roles as appropriate. Note: Children reaching age 18 without meeting full membership requirements are removed from the children's register and treated as visitors until they complete membership qualifications."},{"h":"Qualifications for Membership","a":"qualifications","t":"To become a full member of The Apostles' Church, individuals must meet the following requirements: 1 A personal commitment of faith in Jesus Christ for salvation 2 Baptism by triune immersion as a testimony of salvation 3 Registered at any church branch of The Apostles' Church 4 Completion of foundational lessons on ch"},{"h":"Membership Transfer","a":"transfer","t":""},{"h":"From Another APCH Branch","a":"transfer","t":"Members moving between our congregations require a transfer letter detailing their spiritual standing, leadership involvement, and fulfillment of responsibilities. The new branch enlists them while removing them from their previous branch's active roll."},{"h":"From a Compatible Church","a":"","t":"Individuals from churches with compatible doctrines can join with a recommendation letter confirming good standing and acceptance at the Lord's Table. Additional instruction and confirmation of acceptance of our Statement of Faith may be required."},{"h":"From an Incompatible Church","a":"","t":"Those coming from churches with doctrinal differences must be baptized in The Apostles' Church to be accepted as members, regardless of previous baptism."},{"h":"Members' Rights & Responsibilities","a":"rights","t":"Consistent with our Constitution , every member enjoys specific rights and carries important responsibilities: Participation Rights Every active member has the right to participate in all church matters including financial affairs and administration. Worship Commitment Responsibility to attend divine services, worship "},{"h":"Membership Management","a":"management","t":""},{"h":"Exclusion from Membership","a":"management","t":"Members may be removed from the church roll for: Gross indiscipline Transfer to a different church Apostasy (abandonment of faith) Death"},{"h":"Restoration of Members","a":"","t":"Former members can be restored by vote of the assembly from which they were dismissed or unanimous agreement of church officers, following the biblical principle of restoration found in: \"Now instead, you ought to forgive and comfort him, so that he will not be overwhelmed by excessive sorrow. I urge you, therefore, to"},{"h":"Ready to Join Our Community?","a":"","t":"Become part of a vibrant faith community dedicated to worship, service, and spiritual growth. Begin Membership Process Contact Membership Office"}]},{"u":"news.html","t":"News & Updates","d":"Latest news, events, and updates from The Apostles","c":"News","s":[{"h":"News & Updates","a":"","t":"Stay informed with the latest news, events, and spiritual insights from The Apostles' Church community."},{"h":"Latest News","a":"news-title","t":"All News Announcements Events Sermons Community Ministry Updates April 15, 2025 Announcements"},{"h":"Annual Community Easter Celebration Draws Record Attendance","a":"","t":"Our church hosted its largest Easter celebration yet, with over 1,200 community members joining us for a day of worship, fellowship, and service. The event featured special musical performances, children's activities, and a community meal that brought together people from all walks of life. Read Full Story April 10, 20"},{"h":"New Sermon Series: \"Walking in Faith Through Uncertain Times\"","a":"","t":"Join us for a transformative 8-week sermon series exploring how to maintain strong faith during life's challenges. Starting this Sunday, Pastor James will guide us through biblical principles for finding peace and purpose. Read More April 8, 2025 Ministry Updates"},{"h":"Youth Ministry Launches Summer Discipleship Program","a":"","t":"Our youth ministry is excited to announce \"Rooted in Faith,\" a summer program designed to help teenagers develop deeper spiritual foundations through Bible study, mentorship, and service projects. Read More April 5, 2025 Community"},{"h":"Community Food Pantry Expansion Completed","a":"","t":"Thanks to generous donations and volunteer efforts, our community food pantry has expanded its capacity by 40%. The upgraded facility will serve over 500 families monthly, providing essential groceries and spiritual support. Read More April 3, 2025 Events"},{"h":"Marriage Retreat Registration Now Open","a":"","t":"Strengthen your marriage at our annual couples retreat, \"Building a Covenant Marriage.\" The weekend getaway includes workshops, counseling sessions, and quality time for couples to reconnect spiritually and emotionally. Read More April 1, 2025 Announcements"},{"h":"New Small Group Studies Starting This Month","a":"","t":"Connect with other believers through our new small group studies focusing on prayer, biblical finances, and Christian parenting. Groups meet weekly in various locations throughout the community. Read More"},{"h":"Upcoming Events","a":"events-title","t":"25 APR 6:30 PM - 8:30 PM Sunday Evening"},{"h":"Praise & Worship Night","a":"","t":"Main Sanctuary An evening of powerful worship, prayer, and testimony sharing. All are welcome to experience God's presence in community. Learn More 30 APR 9:00 AM - 12:00 PM Saturday Morning"},{"h":"Community Service Day","a":"","t":"Church Grounds Join us as we serve our local community through various outreach projects. Families encouraged to participate together. Register Now 4 MAY 7:00 PM - 9:00 PM Wednesday Evening"},{"h":"Financial Peace Workshop","a":"","t":"Fellowship Hall Learn biblical principles for financial stewardship, budgeting, and debt reduction in this practical workshop series. Sign Up"},{"h":"Stay Connected","a":"newsletter-title","t":"Subscribe to our weekly newsletter to receive the latest news, sermon notes, and event updates directly in your inbox. Subscribe I agree to receive emails from The Apostles' Church and understand I can unsubscribe at any time."}]},{"u":"privacy.html","t":"Privacy Policy","d":"How The Apostles","c":"Pages","s":[{"h":"Privacy Policy","a":"","t":"How The Apostles' Church handles your information when you use this website."},{"h":"Your Privacy","a":"","t":"Last updated: 21 November 2026 This website is run by The Apostles' Church (APCH), CH80/01 Off Zambezi Road, Lusaka, Zambia. We collect as little information as possible, and we never sell or share it for marketing."},{"h":"Information you choose to send us","a":"","t":"Newsletter sign-up: the newsletter forms open an email to the church secretariat with your email address in it. Nothing is stored by the website itself. We use your address only to send church news, and you can ask to be removed at any time. Emails, calls and messages: if you contact us, we use what you send only to re"},{"h":"Information stored in your browser","a":"","t":"We do not use cookies or tracking tools. The site search remembers your last few searches in your own browser (local storage) so you can repeat them. This never leaves your device, and you can clear it by clearing your browser's site data."},{"h":"Other services this site uses","a":"","t":"To load fonts, icons, styles and some images, your browser connects to outside services: Google Fonts, jsDelivr, unpkg and Unsplash. Like any website, they receive your IP address and browser details when your browser requests a file from them. Links to Facebook, YouTube, WhatsApp and other sites take you to services w"},{"h":"Your choices","a":"","t":"You can ask us what information we hold about you, ask us to correct it, or ask us to delete it. Contact the church secretariat: Email: apchsecretariat@gmail.com Phone: +260 977 441 240 Office hours: Monday-Friday, 10:00 AM - 4:00 PM"},{"h":"Changes to this policy","a":"","t":"If we change how we handle information, we will update this page and the date at the top."}]},{"u":"resources.html","t":"Resources Hub","d":"Explore our comprehensive collection of Bible studies, teachings, and resources for spiritual growth and church life.","c":"Resources","s":[{"h":"Resources Hub","a":"","t":"Explore our comprehensive collection of Bible studies, teachings, and resources designed to strengthen your faith and support your spiritual journey. No resources match your search. Try a different keyword."},{"h":"Featured Resources","a":"featured","t":"Discover our most popular and impactful resources for spiritual growth."},{"h":"Bible Course","a":"","t":"Start your journey with our free interactive Bible study program tailored for all knowledge levels. Enroll Now"},{"h":"Events Calendar","a":"","t":"Stay updated with our weekly services, special events, and community activities. View Schedule"},{"h":"Ministries","a":"","t":"Find your place to serve and grow through our various ministry opportunities. Explore Ministries"},{"h":"Bible Study Resources","a":"bible-study","t":"Deepen your understanding of Scripture with our comprehensive Bible study materials. Study Guide 45 min"},{"h":"Timeless Truths: Foundations of Faith","a":"","t":"Explore the core teachings of Christianity that have stood the test of time and continue to guide believers today. Read Study Comfort Series 60 min"},{"h":"Death, Grief & the Afterlife","a":"","t":"A biblical perspective on loss, mourning, and the hope of eternal life through Jesus Christ. Read Study Prayer Guide 30 min"},{"h":"The Power of Prayer: Connecting with God","a":"","t":"Learn how to develop a meaningful prayer life and experience deeper communion with God. Read Guide Prophecy Study 90 min"},{"h":"Understanding Biblical Prophecy","a":"","t":"Explore fulfilled and future prophecies to understand God's plan throughout history. Read Study Healing Series 50 min"},{"h":"The Gift of Forgiveness","a":"","t":"Discover the transformative power of forgiveness and how to extend grace to others as God has to us. Read Study End Times Study 75 min"},{"h":"Eschatology: The Study of Last Things","a":"","t":"Biblical teachings about Christ's return, the resurrection, and God's ultimate plan for creation. Read Study Spiritual Growth 55 min"},{"h":"The Person and Work of the Holy Spirit","a":"","t":"Understanding the third person of the Trinity and His role in our spiritual lives today. Read Study"},{"h":"Church Life Resources","a":"church-life","t":"Resources for community building, ministry involvement, and church participation. Audio Series Series"},{"h":"Sermons & Teachings Archive","a":"","t":"Access our collection of recent sermons and Bible teachings for personal study and reflection. Browse Archive Interactive Updated"},{"h":"Church Events Calendar","a":"","t":"Stay informed about upcoming worship services, Bible studies, and special events at our church. View Calendar Ministry Guide Guide"},{"h":"Ministries & Service Opportunities","a":"","t":"Discover ways to get involved and use your gifts to serve our church and community. Explore Ministries Volunteer Guide Guide"},{"h":"Volunteer Opportunities","a":"","t":"Find meaningful ways to serve within our church family and make a difference in our community. View Opportunities Prayer Support Submit"},{"h":"Prayer Requests","a":"","t":"Share your prayer needs with our church community and join us in praying for others. Submit Request"},{"h":"Learning & Growth Resources","a":"learning-growth","t":"Educational materials for personal development, family life, and practical Christian living. Interactive Course 12 weeks"},{"h":"Comprehensive Bible Course","a":"","t":"A structured program covering key biblical themes, doctrines, and practical applications for daily life. Start Course FAQ Collection Q&A"},{"h":"Bible Questions Answered","a":"","t":"Clear, biblically-based answers to common questions about Scripture, doctrine, and Christian living. Browse Q&A Wellness Guide Guide"},{"h":"Finding Peace & Happiness","a":"","t":"Biblical principles for overcoming anxiety, finding contentment, and experiencing true joy in Christ. Read Guide Family Resources Series"},{"h":"Marriage & Family Resources","a":"","t":"Biblical guidance for building strong, God-centered marriages and raising children in faith. Explore Resources Youth Ministry For Teens"},{"h":"Youth & Young Adult Resources","a":"","t":"Specialized materials addressing the unique spiritual needs and challenges facing today's youth. Browse Resources Apologetics Study"},{"h":"Science & the Bible","a":"","t":"Exploring the harmony between scientific discovery and biblical revelation in creation and history. Read Study"},{"h":"Quick Access","a":"","t":"Get immediate access to our most requested resources and services."},{"h":"Daily Bible Reading Plan","a":"","t":"One-year plan with daily readings and reflections"},{"h":"Weekly Prayer Guide","a":"","t":"Structured prayers for personal and intercessory prayer"},{"h":"Sermon Notes Template","a":"","t":"Printable template for taking notes during sermons"},{"h":"Family Devotion Ideas","a":"","t":"Simple, engaging activities for family spiritual time"},{"h":"Service Recordings","a":"","t":"Watch or listen to recent worship services"},{"h":"Contact a Pastor","a":"","t":"Request prayer, counseling, or spiritual guidance"}]},{"u":"theName.html","t":"The Name","d":"The meaning behind the name of The Apostles","c":"Faith & Beliefs","s":[{"h":"The Meaning of Our Name","a":"","t":"\"You shall be called by a new name that the mouth of the LORD will bestow.\" - Isaiah 62:2"},{"h":"Why \"Apostles\"?","a":"the-name","t":"Apostles is the new name that Yahweh gave to His chosen people who seek His Kingdom and His righteousness (Luke 6:13; Matthew 6:33). This prophetic name was foretold by Isaiah: And the Gentiles shall see thy righteousness, and all kings thy glory: and thou shalt be called by a new name, which the mouth of the LORD shal"},{"h":"Biblical Significance of Our Name","a":"","t":""},{"h":"A Chosen People","a":"","t":"As Yahweh's servants and chosen people, we are a new tribe and holy nation, a royal priesthood of His Kingdom."},{"h":"New Covenant","a":"","t":"Founded on a new covenant written not on stone tablets but on the tablets of our hearts (Jeremiah 31:33)."},{"h":"Divine Union","a":"","t":"We are united through the blood and body of Yehoshua HaMeshiach, becoming one family in Him."},{"h":"Our Apostolic Identity","a":"","t":"When we partake of the divine through communion, our lips are touched by Yahweh's power, removing our iniquity and atoning for our sins (Isaiah 6:6-7). In this spiritual nourishment, we undergo an Ezekielian experience:"},{"h":"Spiritual Nourishment","a":"","t":"Eating the scroll of God's Word, making it sweet as honey in our mouths (Ezekiel 3:1-3)."},{"h":"Global Commission","a":"","t":"Commissioned to speak to all creation, not just those of familiar speech (Mark 16:15-18)."},{"h":"Divine Tongues","a":"","t":"Speaking through the Holy Spirit in various tongues as at Pentecost (Acts 2:3-4)."},{"h":"The Apostolic Ministries","a":"","t":"The ultimate goal of the Gospel is to unite all peoples into one tribe or nation of one faith and knowledge of Yahweh through Yehoshua HaMeshiach. This tribal nation is the body that is perfected and edified by its founding father, Yehoshua, who is the Chief Apostle and high priest of the order of Melchizedek (Hebrews "},{"h":"Apostolic Prophets","a":"","t":"Proclaiming the culture of our tribal nation through prophetic utterance."},{"h":"Apostolic Evangelists","a":"","t":"Baptizing those who believe in the name of our Chief Apostle."},{"h":"Apostolic Pastors","a":"","t":"Shepherding and nurturing believers to grow in faith and maturity."},{"h":"Apostolic Teachers","a":"","t":"Instructing through study and meditation on the Gospel of our nation. Key Principle: Before one can prophesy, evangelize, shepherd, or teach, one must first acquire the citizenship—to be an apostle. One must be sent, possessing the authority. If not an apostle, then in whose name and by what authority shall one ministe"},{"h":"Unity in the Apostolic Name","a":"","t":"When Yehoshua named His disciples apostles (Luke 6:12-13), He reconciled and united Himself with them through this name. His prayer in John 17 reveals His desire for unity—that all believers would be one with Him and with each other. And when it was day, he called unto him his disciples: and of them he chose twelve, wh"},{"h":"Join the Apostolic Family","a":"","t":"Become part of the holy nation, a royal priesthood, and fellow citizens with the saints in God's household. Become a Member Read Our Articles of Faith"}]},{"u":"resources/Practical-commitments.html","t":"Practical Commitments","d":"The practical commitments and biblical foundations of The Apostles","c":"Resources","s":[{"h":"The Apostles' Church: Who Are We","a":"","t":"Our practical commitments flow from our faith in Jesus Christ and our desire to live according to His Word, guided by the apostles' teaching and the leading of the Holy Spirit."},{"h":"The Name","a":"","t":"We commit to the name Apostles as given by the Lord Jesus Christ Himself, who is the Chief Apostle (Luke 6:12–13; Hebrews 3:1). In His divine purpose, He called and named His disciples apostles, setting them apart as a chosen people to seek first the Kingdom of God and His righteousness (Matthew 6:33). This calling ful"},{"h":"Sanctity of Marriage","a":"","t":"We uphold the sanctity of marriage as a lifelong covenant between one man and one woman, which is not to be separated except by death. Accordingly, a person living with a spouse other than their first spouse while the former spouse is still living, whether through polygamy or divorce and remarriage, does not qualify fo"},{"h":"Holy Convocation","a":"","t":"We commit to holy fellowship with the saints through prayer, the sharing of psalms, and the study of the Word of God on the eighth day, also known as the first day of the week, which is observed as the Church's Main Divine Service. On this day, believers gather with offerings and tithes. This is the day on which God fi"},{"h":"Solemn Feasts","a":"","t":"We commit to holding General Conferences three times each year in April, July, and October observing them not with the leaven of malice and wickedness, but with the unleavened bread of sincerity and truth, which is Jesus Christ (1 Corinthians 5:7–8; Leviticus 23)."},{"h":"Head Covering","a":"","t":"We adhere to the scriptural instruction that women are to cover their heads during worship, in obedience to the order and teaching set forth in the Scriptures (1 Corinthians 11:14–15)."},{"h":"Modest Appearance","a":"","t":"We commit to dressing in accordance with New Testament teaching, maintaining conformity to Scripture concerning outward adornment. This includes restraint in the use of jewellery and cosmetics that create an unnatural appearance, so that conduct and appearance reflect holiness and devotion to God (1 John 2:15–16; 1 Pet"},{"h":"Total Abstinence","a":"","t":"We commit to total abstinence from the following: Unclean foods and blood Acts 15:28–29; Romans 14:2–3, 17; 1 Corinthians 8:8; 1 Timothy 4:1–5 All liquor and strong drink Proverbs 20:1; 23:29–32; Isaiah 28:7; 1 Corinthians 5:11; 6:10 The use of tobacco in any form, opium, morphine, and other harmful drugs Isaiah 55:2; "},{"h":"Biblical Foundation","a":"","t":"\"Having therefore these promises, dearly beloved, let us cleanse ourselves from all filthiness of the flesh and spirit, perfecting holiness in the fear of God.\" — 2 Corinthians 7:1"},{"h":"Our Commitment to Holiness","a":"","t":"These practical commitments reflect our desire to live in obedience to God's Word, to honor Jesus Christ in all things, and to be a people set apart for His purposes. We invite all who share these convictions to join us in this journey of faith. \"But ye are a chosen generation, a royal priesthood, an holy nation, a pec"}]},{"u":"resources/bible-questions.html","t":"Bible Questions Answered","d":"Join The Apostles","c":"Resources","s":[{"h":"Bible Questions Answered","a":"","t":"The Bible addresses the deepest questions of life, faith, purpose, and eternity. At The Apostles' Church, we believe the Holy Scriptures are the inspired and authoritative Word of Jehovah God and provide trustworthy answers for every generation."},{"h":"Who Is God?","a":"","t":"God is the eternal Creator of heaven and earth. He is holy, loving, just, and faithful. The Bible reveals one true God who desires a relationship with humanity and who governs all creation with wisdom and compassion (Genesis 1:1; Psalm 145:8–9). \"In the beginning God created the heavens and the earth.\" — Genesis 1:1"},{"h":"Who Is Jesus Christ?","a":"","t":"Jesus Christ is the eternal Son of God who became human without ceasing to be divine. He lived a sinless life, died on the cross for the forgiveness of sins, rose bodily from the dead, and ascended into heaven. He will return again in glory as Lord and King (John 1:1–14; 1 Corinthians 15:3–4)."},{"h":"What Is Salvation?","a":"","t":"Salvation is God's free gift of eternal life, received by grace through faith in Jesus Christ. It brings forgiveness of sins, reconciliation with God, and transformation of life. Salvation cannot be earned by human effort but is received through repentance and faith (Ephesians 2:8–9; Romans 10:9–10)."},{"h":"Why Does God Allow Suffering?","a":"","t":"The Bible teaches that suffering entered the world through sin, yet God remains present and active in human pain. He uses suffering to draw people to Himself, to shape character, and to reveal His glory. In Christ, suffering is not the end; hope and restoration are promised (Romans 8:18; John 16:33)."},{"h":"What Happens After Death?","a":"","t":"Death does not end existence. The Bible teaches a bodily resurrection and a final judgement. Those who belong to Christ will enjoy eternal life with God, while those who reject Him face eternal separation (1 Corinthians 15; Revelation 21:1–8)."},{"h":"Have More Questions?","a":"","t":"We'd love to help you find biblical answers to your questions. Contact Us"}]},{"u":"resources/faith-god.html","t":"Faith in God","d":"Understanding and growing in faith through biblical principles and practical guidance.","c":"Resources","s":[{"h":"Faith in God","a":"","t":"Faith is central to the Christian life. It is through faith that believers receive salvation and learn to live in daily dependence on God."},{"h":"What Is Faith?","a":"","t":"Faith is confident trust in God's character, promises, and Word. It involves believing in God's truth and acting in obedience, even when circumstances are unclear (Hebrews 11:1, 6)."},{"h":"Faith and Salvation","a":"","t":"Salvation is received by faith in Jesus Christ. This faith leads to repentance, transformation, and a lifelong journey of following Christ (Romans 3:22–24)."},{"h":"Growing in Faith","a":"","t":"Faith grows through prayer, reading the Bible, worship, fellowship, and obedience. As believers walk with God, their trust in Him deepens (Romans 10:17). Ways to Grow in Faith: Daily Devotion Regular prayer and Bible study strengthen spiritual foundations. Christian Fellowship Worship and community with believers encou"},{"h":"Faith in Difficult Times","a":"","t":"Trials test and refine faith. The Bible encourages believers to persevere, knowing that God is faithful and works all things for good (James 1:2–4; Romans 8:28)."},{"h":"Faith Expressed Through Action","a":"","t":"True faith produces good works. While works do not save, they are evidence of a living and active faith (James 2:17). \"Now faith is confidence in what we hope for and assurance about what we do not see.\" — Hebrews 11:1 Explore More Resources"}]},{"u":"resources/marriage-family.html","t":"Marriage & Family","d":"Biblical guidance for building strong, God-centered relationships and families.","c":"Resources","s":[{"h":"Marriage & Family","a":"","t":"Marriage and family are God's gift to humanity and are central to His design for society and spiritual growth."},{"h":"God's Design for Marriage","a":"","t":"Marriage is a covenant relationship between one man and one woman, instituted by God and intended to reflect His love, faithfulness, and unity (Genesis 2:24; Matthew 19:4–6)."},{"h":"Love and Mutual Respect","a":"","t":"The Bible teaches mutual love, respect, and submission within marriage. Husbands and wives are called to serve one another in Christlike love (Ephesians 5:21–33). \"Submit to one another out of reverence for Christ.\" — Ephesians 5:21"},{"h":"Raising Godly Children","a":"","t":"Parents are entrusted with nurturing children in love, discipline, and the knowledge of God. The Church supports families in this sacred responsibility (Deuteronomy 6:6–7; Proverbs 22:6). Model Christlike character and values Teach God's Word through daily living Establish regular family worship Pray together as a fami"},{"h":"Healing and Forgiveness in Families","a":"","t":"All families face challenges. Through forgiveness, prayer, and biblical guidance, broken relationships can be restored and strengthened (Colossians 3:13–14)."},{"h":"The Family and the Church","a":"","t":"The Church is a spiritual family where individuals and households receive encouragement, accountability, and care. Together, we grow in faith and support one another through every season of life."},{"h":"Family Ministry Resources","a":"","t":"Marriage Enrichment Workshops, counseling, and retreats for couples at every stage. Parenting Classes Biblical principles and practical guidance for raising children. Family Retreats Annual retreats for spiritual refreshment and family bonding. Young Families Group Support and fellowship for parents with young children"}]},{"u":"resources/peace-happiness.html","t":"Peace & Happiness","d":"Biblical principles for finding true peace and lasting joy in Christ.","c":"Resources","s":[{"h":"Peace & Happiness","a":"","t":"Many people search for peace and happiness, yet true and lasting fulfillment is found only in a right relationship with God."},{"h":"The Source of True Peace","a":"","t":"Biblical peace is not merely the absence of trouble but wholeness and reconciliation with God. Through Jesus Christ, believers experience peace that surpasses human understanding (Romans 5:1; Philippians 4:6–7)."},{"h":"Joy That Endures","a":"","t":"Happiness based on circumstances is temporary, but joy rooted in Christ endures through every season of life. This joy is a fruit of the Holy Spirit and a strength to the believer (Galatians 5:22; Nehemiah 8:10)."},{"h":"Overcoming Anxiety and Fear","a":"","t":"The Bible invites believers to bring every concern to God in prayer. Trust in God's promises brings comfort, courage, and stability in uncertain times (Isaiah 41:10; 1 Peter 5:7). \"Do not be anxious about anything, but in every situation, by prayer and petition, with thanksgiving, present your requests to God.\" — Phili"},{"h":"Healing for the Brokenhearted","a":"","t":"God cares deeply for those who are hurting. Through prayer, Scripture, and the support of the Church, individuals can experience healing, restoration, and renewed hope (Psalm 34:18; Revelation 21:4)."},{"h":"Practical Steps to Peace & Joy","a":"","t":"Begin each day with prayer and Scripture reading Practice gratitude by keeping a blessings journal Participate in worship and fellowship regularly Serve others to shift focus from self to others Memorize and meditate on God's promises"}]},{"u":"resources/science-bible.html","t":"Science & the Bible","d":"Exploring the harmony between scientific discovery and biblical truth.","c":"Resources","s":[{"h":"Science & the Bible","a":"","t":"The Bible and science address different questions but are not in conflict. Scripture reveals who created the universe and why, while science explores how creation functions."},{"h":"God the Creator","a":"","t":"The Bible affirms God as the Creator and Sustainer of all things. Creation reflects His wisdom, order, and power (Genesis 1; Psalm 19:1). \"The heavens declare the glory of God; the skies proclaim the work of his hands.\" — Psalm 19:1"},{"h":"The Bible and Scientific Inquiry","a":"","t":"The Bible is not a science textbook but speaks truthfully about reality. Scientific discovery, when rightly understood, can deepen appreciation for God's creation."},{"h":"Human Life and Dignity","a":"","t":"Human beings are created in God's image, giving every person inherent worth and dignity. This belief shapes Christian ethics and respect for life (Genesis 1:26–27)."},{"h":"Faith and Reason","a":"","t":"Christian faith encourages thoughtful reflection and does not reject reason. Believers are called to love God with heart, soul, and mind (Matthew 22:37). \"All truth is God's truth, wherever it may be found.\" — Christian maxim"},{"h":"Ethics and Responsibility","a":"","t":"As science and technology advance, biblical principles guide responsible use, compassion, and respect for human life and the environment. Stewardship of creation (Genesis 2:15) Respect for human dignity at all stages of life Ethical considerations in medical research Responsible technological development Environmental "},{"h":"Areas of Harmony","a":"","t":"Cosmic Order The universe's precise physical constants align with biblical descriptions of God's orderly creation. Biological Complexity Intricate design in living organisms reflects divine craftsmanship. Moral Consciousness Human moral awareness corresponds to being made in God's image."},{"h":"Recommended Reading","a":"","t":"\"The Language of God\" by Francis Collins \"The Case for a Creator\" by Lee Strobel \"Science and Faith\" by C. John Collins \"God's Undertaker\" by John Lennox"}]},{"u":"resources/youth.html","t":"Youth & Young Adults","d":"Resources and guidance for teens and young adults navigating faith in today","c":"Resources","s":[{"h":"Youth & Young Adults","a":"","t":"Young people are vital to the life and future of the Church. God calls them to live with purpose, faith, and courage."},{"h":"Identity in Christ","a":"","t":"True identity is found in being created and redeemed by God. Young people are valued, loved, and called according to God's purpose (1 Peter 2:9)."},{"h":"Faith in a Changing World","a":"","t":"The Bible provides guidance for navigating modern challenges such as peer pressure, media influence, and moral decision-making (Romans 12:2). Common Challenges: Peer Pressure Standing firm in faith among friends and classmates Social Media Navigating digital influence and maintaining authenticity Career Choices Finding"},{"h":"Discovering Purpose and Calling","a":"","t":"God equips young believers with spiritual gifts and talents to serve Him and others. Every calling matters in God's Kingdom (1 Timothy 4:12)."},{"h":"Education, Work, and Integrity","a":"","t":"Faith in God shapes attitudes towards education, work, and leadership. Believers are called to live with honesty, diligence, and excellence (Colossians 3:23)."},{"h":"Community and Belonging","a":"","t":"The Church provides a safe and supportive community where young people can grow spiritually and build meaningful relationships that last a lifetime."},{"h":"Youth Programs & Events","a":"","t":"Youth Bible Study Weekly interactive Bible studies designed for teens and young adults Annual Youth Camp Summer spiritual retreat with worship, teaching, and fellowship Service Projects Community outreach opportunities to serve others in love Leadership Training Developing the next generation of church leaders"}]}];
